                return "\n                    // 1 bar\n                    3.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    3.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                    3.\((noteString).toTemplate()).8 {beam split  tp \((tp).toTemplate())} |\n\n                    5.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    5.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                    5.\((noteString).toTemplate()).8 {beam split  tp \((tp).toTemplate())} |\n\n                    -21.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    -21.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                    -21.\((noteString).toTemplate()).8 {beam split  tp \((tp).toTemplate())} |\n\n                    -19.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    -19.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                    -19.\((noteString).toTemplate()).8 {beam split  tp \((tp).toTemplate())} |\n\n                    15.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    15.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                    15.\((noteString).toTemplate()).8 {beam split  tp \((tp).toTemplate())} |\n\n                    17.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    17.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                    17.\((noteString).toTemplate()).8 {beam split  tp \((tp).toTemplate())} |\n                    \n                    39.\((noteString).toTemplate()).32 {beam split tp \((tp).toTemplate())} \n                    39.\((noteString).toTemplate()).16 {beam split  tp \((tp).toTemplate())} \n                   